import{_ as o,o as a,c as r,a6 as n}from"./chunks/framework.CKIbuWFA.js";const p=JSON.parse('{"title":"Gerencie conexões com LIVE","description":"","frontmatter":{"title":"Gerencie conexões com LIVE","docId":"user.live.connections","translationKey":"user.live.connections","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"37f7274550d3010051ab456da2a2091b650e5e7aaaf30756b6695435bcfc08c7","translationRevision":"85e930959fb8374b92c8dcb000a83d5b706c61651518b47567b2ee8b4ded7a1e","order":10},"headers":[],"relativePath":"pt/user/live/connections.md","filePath":"pt/user/live/connections.md","lastUpdated":1794611623000}'),t={name:"pt/user/live/connections.md"};function i(s,e,c,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="manage-live-connections" tabindex="-1">Gerencie conexões com LIVE <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to &quot;Gerencie conexões com LIVE {#manage-live-connections}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conecte-se a um criador específico, entenda a reconexão e configure servidores de plugins de forma independente. Você precisa de uma <a href="./../installation.html">instalação de desktop</a> funcional, acesso à rede e o identificador do criador. Confira os <a href="./../requirements.html">requisitos</a> antes de diagnosticar problemas do sistema operacional.</p><h2 id="connect-deliberately" tabindex="-1">Conecte-se de forma consciente <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to &quot;Conecte-se de forma consciente {#connect-deliberately}&quot;">​</a></h2><ol><li>Abra <strong>Connections</strong>. Digite o identificador, com ou sem <code>@</code>; um nome de exibição não é o mesmo identificador.</li><li>Comece com <strong>Use Cookie</strong> desligado. Se o TikTok exigir uma sessão autorizada, ative-o e digite o cookie apenas no campo mascarado. Cookies permanecem na memória; não os cole em diagnósticos nem configurações do Cloud.</li><li>Deixe <strong>Monitor and auto-connect</strong> desligado para uma tentativa direta e selecione <strong>Connect</strong>. Leia o status e qualquer erro antes de tentar novamente.</li><li>Confira no <a href="./feed.html">Live feed</a> o criador correto e um evento novo. Uma sala conectada, mas silenciosa, pode não mostrar atividade.</li><li>Use <strong>Reconnect</strong> para o mesmo criador ou <strong>Disconnect</strong> antes de trocar de criador. Durante uma tentativa em andamento, <strong>Cancel</strong> interrompe essa tentativa.</li></ol><p>Após uma conexão direta bem-sucedida, ative o monitoramento para aguardar um criador entrar ao vivo. Esperar e verificar são diferentes de estar conectado. Pare o monitoramento antes de editar um identificador bloqueado. Selecionar um criador recente inicia uma conexão; faz mais do que preencher o campo.</p><p>O explorador oferece salas descobertas, mas os resultados podem ficar desatualizados. Atualize antes de presumir que uma sala ainda está disponível. As conexões de servidores de plugins no painel inferior configuram seus próprios serviços; um plugin conectado não estabelece autenticação no TikTok ou no Cloud.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Conexões diretas, monitoramento e controles de conexão de plugins estão disponíveis. Reconectar ao mesmo criador preserva o contexto do feed atual; trocar de criador inicia outro contexto. O acesso real ao TikTok depende da sala e da sessão no serviço e não é garantido por um teste local bem-sucedido.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para salas offline, verifique se o criador está ao vivo. Para erros de sessão ou limite de requisições, siga a condição informada para tentar novamente. Cliques repetidos em reconectar não renovam a autenticação. Use a <a href="./../preferences/troubleshooting.html">solução de problemas</a> para coletar o componente com falha e o horário sem expor credenciais.</p>',11)])])}const f=o(t,[["render",i]]);export{p as __pageData,f as default};
